   120	import hotel.rooms.Room;
   121	import java.math.BigDecimal;
   122	import java.math.RoundingMode;
   123	import java.time.LocalDate;
   124	import java.time.Month;
   125	
   126	/**
   127	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
   128	 * high-season nights; the rate plan then prices the stay from that sum (a discount, or a closed price). Money is rounded to cents
   129	 * (half-even) at every step.
   130	 */
   131	public final class PriceCalculator {
   132	
   133	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
   134	
   135	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
   136	        return calculate(room, checkIn, checkOut, ratePlan, null);
   137	    }
   138	
   139	    public Price calculate(
   140	            Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
   141	        ratePlan.validate(checkIn, checkOut, companyCode);
   142	        int nights = 0;
   143	        BigDecimal subtotal = cents(BigDecimal.ZERO);
   144	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
   145	            subtotal = subtotal.add(nightPrice(room, night));
   146	            nights++;
   147	        }
   148	        return ratePlan.price(room, nights, subtotal, companyCode);
   149	    }
   150	
   151	    BigDecimal nightPrice(Room room, LocalDate night) {
   152	        BigDecimal nightlyRate = room.nightlyRate();
   153	        if (isHighSeason(night)) {
   154	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
   155	        }
   156	        return cents(nightlyRate);
   157	    }
   158	
   159	    /** High season: from December 15 to the end of February, and the whole of July. */
   160	    static boolean isHighSeason(LocalDate date) {
   161	        Month month = date.getMonth();
   162	        return month == Month.JANUARY
   163	                || month == Month.FEBRUARY
   164	                || month == Month.JULY
   165	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
   166	    }
   167	
   168	    static BigDecimal cents(BigDecimal value) {
   169	        return value.setScale(2, RoundingMode.HALF_EVEN);
   170	    }
   171	}
