   140	            Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
   141	        ratePlan.validate(checkIn, checkOut, companyCode);
   142	        int nights = 0;
   143	        BigDecimal subtotal = cents(BigDecimal.ZERO);
   144	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
   145	            subtotal = subtotal.add(nightPrice(room, night));
   146	            nights++;
   147	        }
   148	        return ratePlan.price(room, nights, subtotal, companyCode);
   149	    }
