   151	    BigDecimal nightPrice(Room room, LocalDate night) {
   152	        BigDecimal nightlyRate = room.nightlyRate();
   153	        if (isHighSeason(night)) {
   154	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
   155	        }
   156	        return cents(nightlyRate);
   157	    }
